import{_ as t,o as e,c as r,ag as o}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"使用数据点配置报警","description":"为数值、状态或组合输入设置报警，试算触发与恢复，并核对通知、历史和正式运行边界。","frontmatter":{"title":"使用数据点配置报警","description":"为数值、状态或组合输入设置报警，试算触发与恢复，并核对通知、历史和正式运行边界。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/point-alarms.md","filePath":"zh/使用指南/使用数据点配置报警.md"}'),i={name:"zh/guide/point-alarms.md"};function n(l,a,s,p,h,d){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="使用数据点配置报警" tabindex="-1">使用数据点配置报警 <a class="header-anchor" href="#使用数据点配置报警" aria-label="Permalink to &quot;使用数据点配置报警&quot;">​</a></h1><p>报警根据已有数据点及条件判断触发和恢复。先核对点的完整路径、类型、单位、质量和更新方式，再设置阈值，不先对一个不明来源的数值报警。</p><p>入口：<strong>数据中心 → 报警单元</strong>。AI 已创建规则时，先在“报警配置”按数据点或报警名称搜索，核对目录和筛选。</p><h2 id="_1-选择入口和数据点" tabindex="-1">1. 选择入口和数据点 <a class="header-anchor" href="#_1-选择入口和数据点" aria-label="Permalink to &quot;1. 选择入口和数据点&quot;">​</a></h2><ul><li>从“报警配置”点击 <strong>“新建报警”</strong>，选择实际工程数据点。</li><li>从数据点列表可通过 **“查看报警配置”**定位已有规则；批量创建使用“创建报警”，先核对点位和数量。</li><li>多个点共同决定条件时，使用 <strong>“组合报警”</strong>，核对每个输入及其变量名。</li></ul><p>不要把数据点详情中的报警摘要当成完整编辑界面，也不要在数据点列表里只搜报警名称判断规则是否存在。</p><h2 id="_2-根据类型设置条件" tabindex="-1">2. 根据类型设置条件 <a class="header-anchor" href="#_2-根据类型设置条件" aria-label="Permalink to &quot;2. 根据类型设置条件&quot;">​</a></h2><p>数值点可配置高低限等条件；布尔、文本、质量、离线和未更新等情况，按当前点类型及界面提供的条件选择。类型不兼容时先调整输入，不强行把对象转换成阈值。</p><p>数值入门可只启用一个所需高限，填写阈值、级别和文本，并关闭本次不需要的其他条件。核对温度等单位，避免摄氏与华氏阈值混用。</p><p>“触发延时”“清除延时”和“死区”影响何时进入与退出报警。单规则编辑器的延时使用毫秒；快速配置中的“持续后触发”使用秒，应以所在字段单位为准。</p><p>组合报警至少需要两个输入点，表达式变量名要与所选点对应。表达式和结果条件的类型分别核对，不把变量改名当成数据点路径改名。</p><h2 id="_3-用样本试算触发与恢复" tabindex="-1">3. 用样本试算触发与恢复 <a class="header-anchor" href="#_3-用样本试算触发与恢复" aria-label="Permalink to &quot;3. 用样本试算触发与恢复&quot;">​</a></h2><p>打开规则的 <strong>“开发调试”</strong>，准备样本值、质量、时间偏移以及需要的离线或源时间信息，点击 <strong>“试算”</strong>。</p><p>不要只试一个越限值。还应核对正常值、恢复值、持续时间、坏质量或长期未更新时的行为，查看“试算过程”和最终状态。</p><p><strong>试算使用填写的样本与草稿，不等于保存了规则、生成了现场报警或送达通知。</strong> 时间延时存在时，样本序列必须覆盖所需时间。</p><p>输入质量导致“判定暂停”时，不等于条件已恢复，也不能把异常值当作正常零值。</p><h2 id="_4-保存并在原位置找回" tabindex="-1">4. 保存并在原位置找回 <a class="header-anchor" href="#_4-保存并在原位置找回" aria-label="Permalink to &quot;4. 保存并在原位置找回&quot;">​</a></h2><p>点击 **“保存报警配置”**或当前编辑器提供的保存操作，确认结果，再回“报警配置”搜索同一规则，核对点位、条件摘要、目录和启用状态。</p><p>出现重叠条件提示时，检查是否误建了重复规则。同一点同种或重叠条件可能将来同时活动，不为完成保存直接确认。</p><p>AI 创建的报警也在这里维护；“AI 参与过”筛选主要位于数据点列表，不能替代按报警名称核对。</p><h2 id="_5-通知和历史分别准备" tabindex="-1">5. 通知和历史分别准备 <a class="header-anchor" href="#_5-通知和历史分别准备" aria-label="Permalink to &quot;5. 通知和历史分别准备&quot;">​</a></h2><ul><li><strong>通知设置</strong>：检查渠道、规则是沿用工程设置还是单独设置，以及触发、恢复的通知选择。测试渠道可能真实发送消息，先取得授权。</li><li><strong>报警历史</strong>：核对报警记录的保存设置，它与数据点历史采样不同。</li><li>正式运行：确认部署采用新工程配置、报警引擎和输入链路均正常，再验证真实触发、恢复和消息送达。</li></ul><p>不要把通知测试成功当成真实条件已经触发，也不要把规则“已启用”当成报警引擎健康。</p><h2 id="_6-活动报警不能靠删除处理" tabindex="-1">6. 活动报警不能靠删除处理 <a class="header-anchor" href="#_6-活动报警不能靠删除处理" aria-label="Permalink to &quot;6. 活动报警不能靠删除处理&quot;">​</a></h2><p><strong>存在活动报警时，不要随意停用或删除规则。</strong> 它可能失去清警路径，并阻止报警角色后续启动；先在运行态确认状态，按条件恢复及交付安排处理。</p><p>删除规则也不等于清除了节点历史数据。批量操作前核对当前页、全部结果与选择数量。</p><p>下一步：<a href="/induframe-docs/zh/guide/data-flow-tutorial.html">联动示例</a> · <a href="/induframe-docs/zh/guide/point-history.html">数据点历史存储</a> · <a href="/induframe-docs/zh/guide/deployments.html">工程部署</a>。</p>',27)])])}const c=t(i,[["render",n]]);export{u as __pageData,c as default};
